style.css:
/* Autobot Hotshot — G1 Hot Rod */
/* i really want this to be global */

/* swap these colors to tune the look */
:root {
  --my-red: #d92332;
  --my-orange: #ff6729;
  --my-yellow: #ffd447;
  --my-pink: #ed4b91;
  --my-dark: #191b24;
  --my-light: #fff0d5;
}

/* dark metallic atmosphere */
html,
body {
  background-color: var(--my-dark) !important;
  color: var(--my-light) !important;
  font-family: "Arial", "Trebuchet MS", sans-serif !important;
}

/* fiery links */
a {
  color: var(--my-yellow) !important;
  text-decoration-color: var(--my-orange) !important;
}

a:hover {
  color: var(--my-pink) !important;
}

/* bold racing-inspired headings */
h1, h2, h3, h4 {
  color: var(--my-red) !important;
  font-weight: 900 !important;
  letter-spacing: -0.04em !important;
}

/* give images a little showroom polish */
img,
video {
  border-radius: 8px !important;
}

/* metallic selection */
::selection {
  background: var(--my-orange) !important;
  color: var(--my-dark) !important;
}
